/**
 * Creates a debounced version of the provided function.
 *
 * The debounced function will only invoke the original function after a specified
 * delay (`ms`) has elapsed since the last call. If the debounced function is
 * called again before the delay expires, the timer is reset.
 *
 * The returned function also exposes a `cancel()` method that clears any pending
 * invocation, preventing the original function from being called.
 *
 * @template T - The type of the original function.
 * @param fn - The function to debounce.
 * @param ms - The delay in milliseconds before the function should be invoked.
 * @returns A debounced function with a `cancel()` method.
 *
 * @example
 * const logInput = debounce((value: string) => {
 *   console.log(`Input: ${value}`);
 * }, 300);
 *
 * logInput("hello");
 * logInput("hello world");
 * // After 300ms, logs: "Input: hello world"
 *
 * logInput.cancel(); // Cancels any pending invocation
 */
function debounce<T extends (...args: any[]) => void>(fn: T, ms: number): T & { cancel(): void } {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  const debounced = (...args: Parameters<T>): void => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      fn(...args);
      timeoutId = null;
    }, ms);
  };

  const debouncedWithCancel = debounced as T & { cancel(): void };

  debouncedWithCancel.cancel = (): void => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debouncedWithCancel;
}
